-- ----------------------------------------------------------------------------
-- 2.18 inventory_transactions: add deferred FKs to jobs and job_operations
-- ----------------------------------------------------------------------------
-- We declared inventory_transactions before jobs / job_operations existed in
-- the new schema (so its restrict_transaction_update_to_notes trigger could
-- be wired up close to the table). Now that jobs and job_operations exist,
-- add the FKs.

ALTER TABLE public.inventory_transactions
    ADD CONSTRAINT inventory_transactions_job_id_fkey
    FOREIGN KEY (job_id) REFERENCES public.jobs(id) ON DELETE SET NULL;

ALTER TABLE public.inventory_transactions
    ADD CONSTRAINT inventory_transactions_job_operation_id_fkey
    FOREIGN KEY (job_operation_id) REFERENCES public.job_operations(id) ON DELETE SET NULL;

-- ============================================================================
-- Phase 3: Functions and triggers
-- ============================================================================

-- ----------------------------------------------------------------------------
-- 3.1 restrict_transaction_update_to_notes — locks down inventory ledger
-- ----------------------------------------------------------------------------
-- Recreated against the renamed column (part_id, was inventory_item_id).
-- Same semantics as before: only `notes` is mutable post-insert.

CREATE OR REPLACE FUNCTION public.restrict_transaction_update_to_notes()
RETURNS trigger
LANGUAGE plpgsql
AS $function$
BEGIN
    IF OLD.company_id          IS DISTINCT FROM NEW.company_id
       OR OLD.part_id          IS DISTINCT FROM NEW.part_id
       OR OLD.item_name        IS DISTINCT FROM NEW.item_name
       OR OLD.type             IS DISTINCT FROM NEW.type
       OR OLD.quantity         IS DISTINCT FROM NEW.quantity
       OR OLD.unit             IS DISTINCT FROM NEW.unit
       OR OLD.converted_quantity IS DISTINCT FROM NEW.converted_quantity
       OR OLD.job_id           IS DISTINCT FROM NEW.job_id
       OR OLD.job_operation_id IS DISTINCT FROM NEW.job_operation_id
       OR OLD.operator_id      IS DISTINCT FROM NEW.operator_id
       OR OLD.created_at       IS DISTINCT FROM NEW.created_at
       OR OLD.created_by       IS DISTINCT FROM NEW.created_by
       OR OLD.has_discrepancy  IS DISTINCT FROM NEW.has_discrepancy
    THEN
        RAISE EXCEPTION 'Only the notes field can be updated on inventory transactions';
    END IF;
    RETURN NEW;
END;
$function$;

DROP TRIGGER IF EXISTS enforce_transaction_notes_only_update ON public.inventory_transactions;
CREATE TRIGGER enforce_transaction_notes_only_update
    BEFORE UPDATE ON public.inventory_transactions
    FOR EACH ROW EXECUTE FUNCTION public.restrict_transaction_update_to_notes();

-- ----------------------------------------------------------------------------
-- 3.2 compute_job_status — derives jobs.status from its child job_parts
-- ----------------------------------------------------------------------------
-- Verbatim from the prior schema (operates on job_parts, no schema change).

CREATE OR REPLACE FUNCTION public.compute_job_status(p_job_id uuid)
RETURNS text
LANGUAGE plpgsql
STABLE
AS $function$
DECLARE
    v_total int;
    v_cancelled int;
    v_shipped int;
    v_completed int;
    v_in_progress int;
BEGIN
    SELECT
      count(*),
      count(*) FILTER (WHERE status = 'cancelled'),
      count(*) FILTER (WHERE status = 'shipped'),
      count(*) FILTER (WHERE status = 'completed'),
      count(*) FILTER (WHERE status = 'in_progress')
    INTO v_total, v_cancelled, v_shipped, v_completed, v_in_progress
    FROM job_parts
    WHERE job_id = p_job_id;

    IF v_total = 0 THEN RETURN 'not_started'; END IF;
    IF v_cancelled = v_total THEN RETURN 'cancelled'; END IF;
    IF v_shipped = v_total THEN RETURN 'shipped'; END IF;
    IF v_completed + v_shipped = v_total THEN RETURN 'completed'; END IF;
    IF v_in_progress > 0 OR v_completed > 0 OR v_shipped > 0 THEN RETURN 'in_progress'; END IF;
    RETURN 'not_started';
END;
$function$;

-- ----------------------------------------------------------------------------
-- 3.3 sync_job_status_from_parts — keeps jobs.* in sync with child rollup
-- ----------------------------------------------------------------------------
-- Verbatim from the prior schema.

CREATE OR REPLACE FUNCTION public.sync_job_status_from_parts()
RETURNS trigger
LANGUAGE plpgsql
AS $function$
DECLARE
    v_job_id uuid;
    v_new_status text;
    v_now timestamptz := now();
BEGIN
    v_job_id := COALESCE(NEW.job_id, OLD.job_id);
    v_new_status := compute_job_status(v_job_id);

    UPDATE jobs
    SET status = v_new_status,
        status_changed_at = CASE WHEN status IS DISTINCT FROM v_new_status THEN v_now ELSE status_changed_at END,
        started_at = CASE
            WHEN started_at IS NULL AND v_new_status IN ('in_progress','completed','shipped')
              THEN v_now ELSE started_at END,
        completed_at = CASE
            WHEN v_new_status IN ('completed','shipped') AND completed_at IS NULL THEN v_now
            WHEN v_new_status = 'in_progress' THEN NULL
            ELSE completed_at END,
        shipped_at = CASE
            WHEN v_new_status = 'shipped' AND shipped_at IS NULL THEN v_now
            WHEN v_new_status <> 'shipped' THEN NULL
            ELSE shipped_at END,
        updated_at = v_now
    WHERE id = v_job_id;

    RETURN NULL;
END;
$function$;

DROP TRIGGER IF EXISTS trigger_sync_job_status_from_parts_del ON public.job_parts;
CREATE TRIGGER trigger_sync_job_status_from_parts_del
    AFTER DELETE ON public.job_parts
    FOR EACH ROW EXECUTE FUNCTION public.sync_job_status_from_parts();

DROP TRIGGER IF EXISTS trigger_sync_job_status_from_parts_ins ON public.job_parts;
CREATE TRIGGER trigger_sync_job_status_from_parts_ins
    AFTER INSERT ON public.job_parts
    FOR EACH ROW EXECUTE FUNCTION public.sync_job_status_from_parts();

DROP TRIGGER IF EXISTS trigger_sync_job_status_from_parts_upd ON public.job_parts;
CREATE TRIGGER trigger_sync_job_status_from_parts_upd
    AFTER UPDATE OF status ON public.job_parts
    FOR EACH ROW WHEN (OLD.status IS DISTINCT FROM NEW.status)
    EXECUTE FUNCTION public.sync_job_status_from_parts();

-- ----------------------------------------------------------------------------
-- 3.4 create_job_part_operations_from_routing — rewritten for new schema
-- ----------------------------------------------------------------------------
-- Reads from routing_operations + work_centers (was: routing_nodes +
-- operation_types). Inserts into job_operations with work_center_id and
-- routing_operation_id, snapshotting setup_minutes / cycle_minutes_per_unit
-- onto the existing estimated_setup_minutes / estimated_run_minutes_per_unit
-- columns. Snapshots BOM rows from parts_bom WHERE parent_part_id =
-- (routing's part_id) into job_materials, with the parts_bom_id linkage.
-- Idempotent: NOT EXISTS guard on routing_operation_id / parts_bom_id.

CREATE OR REPLACE FUNCTION public.create_job_part_operations_from_routing(p_job_part_id uuid, p_routing_id uuid)
RETURNS integer
LANGUAGE plpgsql
AS $function$
DECLARE
    v_count integer := 0;
    v_op record;
    v_seq integer := 10;
    v_job_id uuid;
    v_part_id uuid;
    v_min_seq integer;
BEGIN
    SELECT job_id INTO v_job_id FROM job_parts WHERE id = p_job_part_id;
    IF v_job_id IS NULL THEN
        RAISE EXCEPTION 'job_part % not found', p_job_part_id;
    END IF;

    -- The routing's part_id is the parent for any BOM snapshot below.
    SELECT part_id INTO v_part_id FROM routings WHERE id = p_routing_id;
    IF v_part_id IS NULL THEN
        RAISE EXCEPTION 'routing % not found', p_routing_id;
    END IF;

    -- Snapshot routing_operations → job_operations.
    FOR v_op IN
        SELECT ro.*, wc.name AS operation_name
        FROM routing_operations ro
        JOIN work_centers wc ON ro.work_center_id = wc.id
        WHERE ro.routing_id = p_routing_id
          AND NOT EXISTS (
              SELECT 1 FROM job_operations jo
              WHERE jo.job_part_id = p_job_part_id
                AND jo.routing_operation_id = ro.id
          )
        ORDER BY ro.sequence, ro.created_at
    LOOP
        INSERT INTO job_operations (
            job_id, job_part_id, sequence, operation_name, work_center_id,
            instructions, estimated_setup_minutes, estimated_run_minutes_per_unit,
            status, routing_operation_id
        ) VALUES (
            v_job_id, p_job_part_id, v_seq, v_op.operation_name, v_op.work_center_id,
            v_op.instructions, COALESCE(v_op.setup_minutes, 0), v_op.cycle_minutes_per_unit,
            'pending', v_op.id
        );
        v_seq := v_seq + 10;
        v_count := v_count + 1;
    END LOOP;

    -- Snapshot parts_bom (the part's BOM) → job_materials. Idempotent on
    -- parts_bom_id. The BOM is now part-attached, not routing-attached, so
    -- we read parts_bom WHERE parent_part_id = the routing's part.
    INSERT INTO job_materials (job_id, job_part_id, parts_bom_id, material_part_id, expected_quantity, unit)
    SELECT v_job_id, p_job_part_id, b.id, b.child_part_id, b.quantity, b.unit
    FROM parts_bom b
    WHERE b.parent_part_id = v_part_id
      AND NOT EXISTS (
          SELECT 1 FROM job_materials jm
          WHERE jm.job_part_id = p_job_part_id
            AND jm.parts_bom_id = b.id
      );

    -- Set the job_part's current operation cursor to the lowest sequence we wrote.
    SELECT MIN(sequence) INTO v_min_seq FROM job_operations WHERE job_part_id = p_job_part_id;
    IF v_min_seq IS NOT NULL THEN
        UPDATE job_parts SET current_operation_sequence = v_min_seq WHERE id = p_job_part_id;
    END IF;

    RETURN v_count;
END;
$function$;

COMMENT ON FUNCTION public.create_job_part_operations_from_routing(uuid, uuid)
    IS 'Snapshots a routing onto a job_part: routing_operations → job_operations (with work_center_id and routing_operation_id) and parts_bom (where parent_part = routing.part) → job_materials (with parts_bom_id). Idempotent on the snapshot keys. Sets job_parts.current_operation_sequence to the lowest seq written.';

-- ----------------------------------------------------------------------------
-- 3.5 enforce_no_bom_cycles — trigger on parts_bom (BEFORE INSERT/UPDATE)
-- ----------------------------------------------------------------------------
-- Walks the descendants of the proposed child_part_id; if parent_part_id
-- appears in that walk, the new edge would close a cycle. Depth bound 50.
--
-- The unique constraint blocks duplicate edges (A→B twice) and the
-- no-self-reference CHECK blocks A→A, but neither catches A→B + B→A
-- (two distinct rows that both pass both checks but form a 2-cycle). Without
-- this trigger, a 2-cycle would silently corrupt cost rollups.
--
-- The application layer (utils/bomAccess.ts) does the same walk first to
-- give a friendlier error. This trigger is defense-in-depth — it can't be
-- bypassed by direct DB writes, bulk imports that skip the access layer, or
-- future code paths.

CREATE OR REPLACE FUNCTION public.enforce_no_bom_cycles()
RETURNS trigger
LANGUAGE plpgsql
AS $function$
DECLARE
    v_cycle_found boolean;
BEGIN
    WITH RECURSIVE descendants(part_id, depth) AS (
        SELECT NEW.child_part_id, 1
        UNION ALL
        SELECT b.child_part_id, d.depth + 1
        FROM parts_bom b
        JOIN descendants d ON b.parent_part_id = d.part_id
        WHERE d.depth < 50
    )
    SELECT EXISTS (SELECT 1 FROM descendants WHERE part_id = NEW.parent_part_id)
    INTO v_cycle_found;

    IF v_cycle_found THEN
        RAISE EXCEPTION 'Adding BOM edge %→% would create a cycle',
            NEW.parent_part_id, NEW.child_part_id
            USING ERRCODE = 'check_violation';
    END IF;

    RETURN NEW;
END;
$function$;

DROP TRIGGER IF EXISTS parts_bom_no_cycles ON public.parts_bom;
CREATE TRIGGER parts_bom_no_cycles
    BEFORE INSERT OR UPDATE OF parent_part_id, child_part_id ON public.parts_bom
    FOR EACH ROW EXECUTE FUNCTION public.enforce_no_bom_cycles();

-- ----------------------------------------------------------------------------
-- 3.6 recalculate_part_cost — single-level rollup, user-triggered
-- ----------------------------------------------------------------------------
-- Sums (per-internal-op labor) + (per-external-op flat cost) + (per-BOM-child
-- cost × qty). Single-level only: each child's contribution uses that child's
-- current parts.cost_per_unit (no recursion). The stale-cost badge in the UI
-- surfaces when a descendant has changed since the last recalc; the user
-- recalcs bottom-up.
--
-- Cost contract (also documented in the plan and in the routing_operations
-- column comments above):
--
--   Internal op (work_center.kind='internal'):
--     cost = (setup_minutes / 1 + cycle_minutes_per_unit)
--            * COALESCE(labor_rate_override, work_center.labor_rate) / 60
--     The standalone recalc uses qty=1 (UI text: "at qty=1; setup cost
--     amortizes across batch in quotes/jobs.").
--
--   External op (work_center.kind='external'):
--     cost = external_unit_price + (external_setup_cost / 1)
--
--   BOM child:
--     cost = child.cost_per_unit * parts_bom.quantity
--     If parts_bom.unit differs from child.primary_unit, convert via
--     parts_unit_conversions (qty_in_bom_unit * to_primary_factor).
--     If no conversion exists for that pair, RAISE EXCEPTION.
--
-- Updates parts.cost_per_unit and parts.cost_recalculated_at = now(); returns
-- the new cost. Only operates on is_manufacturable parts; for non-
-- manufacturable parts, returns the existing cost_per_unit unchanged.

CREATE OR REPLACE FUNCTION public.recalculate_part_cost(p_part_id uuid)
RETURNS numeric
LANGUAGE plpgsql
AS $function$
DECLARE
    v_is_manufacturable boolean;
    v_routing_id uuid;
    v_total_cost numeric := 0;
    v_op record;
    v_op_cost numeric;
    v_bom record;
    v_child_primary_unit text;
    v_child_cost_per_primary_unit numeric;
    v_to_primary_factor numeric;
    v_qty_in_primary_unit numeric;
BEGIN
    SELECT is_manufacturable INTO v_is_manufacturable FROM parts WHERE id = p_part_id;
    IF v_is_manufacturable IS NULL THEN
        RAISE EXCEPTION 'part % not found', p_part_id;
    END IF;
    IF NOT v_is_manufacturable THEN
        RETURN (SELECT cost_per_unit FROM parts WHERE id = p_part_id);
    END IF;

    SELECT id INTO v_routing_id FROM routings WHERE part_id = p_part_id;

    -- Routing operations (only if a routing exists; some manufacturable parts
    -- may not have one yet, e.g. immediately after creation).
    IF v_routing_id IS NOT NULL THEN
        FOR v_op IN
            SELECT ro.setup_minutes,
                   ro.cycle_minutes_per_unit,
                   ro.labor_rate_override,
                   ro.external_unit_price,
                   ro.external_setup_cost,
                   wc.kind AS wc_kind,
                   wc.labor_rate AS wc_labor_rate
            FROM routing_operations ro
            JOIN work_centers wc ON wc.id = ro.work_center_id
            WHERE ro.routing_id = v_routing_id
        LOOP
            IF v_op.wc_kind = 'internal' THEN
                -- Per the no-silent-fallbacks engineering principle: if neither
                -- the per-op override nor the work-center default rate is set,
                -- we cannot price this operation. Raise rather than silently
                -- treating as $0 cost (which would let users quote at zero
                -- labor without ever seeing the missing data).
                IF v_op.labor_rate_override IS NULL AND v_op.wc_labor_rate IS NULL THEN
                    RAISE EXCEPTION 'Cannot recalculate cost for part %: routing op has no labor rate (neither override nor work_center default)', p_part_id
                        USING ERRCODE = 'check_violation';
                END IF;
                v_op_cost := (COALESCE(v_op.setup_minutes, 0) / 1
                               + COALESCE(v_op.cycle_minutes_per_unit, 0))
                             * COALESCE(v_op.labor_rate_override, v_op.wc_labor_rate)
                             / 60.0;
            ELSE
                -- External op: at least one of unit_price or setup_cost should be
                -- set (a free outside op is meaningless). NULL on both means
                -- the user hasn't filled in pricing yet — refuse to compute.
                IF v_op.external_unit_price IS NULL AND v_op.external_setup_cost IS NULL THEN
                    RAISE EXCEPTION 'Cannot recalculate cost for part %: external routing op has no pricing (neither external_unit_price nor external_setup_cost)', p_part_id
                        USING ERRCODE = 'check_violation';
                END IF;
                v_op_cost := COALESCE(v_op.external_unit_price, 0)
                             + COALESCE(v_op.external_setup_cost, 0) / 1;
            END IF;
            v_total_cost := v_total_cost + v_op_cost;
        END LOOP;
    END IF;

    -- BOM children. Convert BOM unit → child.primary_unit if they differ;
    -- error explicitly when no conversion exists (matches the existing
    -- unknown_* validation pattern).
    FOR v_bom IN
        SELECT b.quantity, b.unit, b.child_part_id,
               c.primary_unit AS child_primary_unit,
               c.cost_per_unit AS child_cost_per_unit
        FROM parts_bom b
        JOIN parts c ON c.id = b.child_part_id
        WHERE b.parent_part_id = p_part_id
    LOOP
        IF v_bom.child_cost_per_unit IS NULL THEN
            -- Per the no-silent-fallbacks principle: a BOM child without a
            -- cost can't contribute to the parent's cost rollup. Raise rather
            -- than treating as $0 (which would let users quote without ever
            -- noticing the missing child cost). The UI should walk the BOM
            -- bottom-up and refuse to recalc the parent until all leaves are
            -- priced.
            RAISE EXCEPTION 'Cannot recalculate cost for part %: BOM child % has no cost_per_unit (recalc the child first)', p_part_id, v_bom.child_part_id
                USING ERRCODE = 'check_violation';
        END IF;

        IF v_bom.unit IS DISTINCT FROM v_bom.child_primary_unit THEN
            SELECT to_primary_factor INTO v_to_primary_factor
            FROM parts_unit_conversions
            WHERE part_id = v_bom.child_part_id
              AND from_unit = v_bom.unit;

            IF v_to_primary_factor IS NULL THEN
                RAISE EXCEPTION 'No unit conversion from % to % for part %',
                    v_bom.unit, v_bom.child_primary_unit, v_bom.child_part_id
                    USING ERRCODE = 'check_violation';
            END IF;

            v_qty_in_primary_unit := v_bom.quantity * v_to_primary_factor;
        ELSE
            v_qty_in_primary_unit := v_bom.quantity;
        END IF;

        v_total_cost := v_total_cost + v_qty_in_primary_unit * v_bom.child_cost_per_unit;
    END LOOP;

    UPDATE parts
    SET cost_per_unit = v_total_cost,
        cost_recalculated_at = now()
    WHERE id = p_part_id;

    RETURN v_total_cost;
END;
$function$;

COMMENT ON FUNCTION public.recalculate_part_cost(uuid)
    IS 'Single-level cost rollup for an is_manufacturable part. Sums internal-op labor + external-op flat cost + (BOM child cost_per_unit * qty, with parts_unit_conversions if BOM unit differs from child primary_unit; raises if no conversion). Uses qty=1 for the standalone recalc (setup amortizes across batch in quotes/jobs). Reads each child cost_per_unit as-is — no recursion. Raises (does not silently fall back to $0) when an internal op has no labor rate, an external op has no pricing, or a BOM child has no cost. Updates parts.cost_per_unit + cost_recalculated_at, returns new cost. For non-manufacturable parts returns existing cost unchanged.';

-- ----------------------------------------------------------------------------
-- 3.7 get_ready_operations_for_station — operator station view
-- ----------------------------------------------------------------------------
--
-- Recreated against work_center_id (renamed from operation_type_id on
-- job_operations). The operator station page calls this to populate a
-- station's "what's next" queue. Same logic as the prior version, just a
-- column rename. Parameter and function name updated to match the
-- work_centers vocabulary.

CREATE OR REPLACE FUNCTION public.get_ready_operations_for_station(
    p_company_id uuid,
    p_work_center_id uuid
)
RETURNS TABLE (
    job_id uuid,
    job_part_id uuid,
    job_operation_id uuid,
    operation_name text,
    op_status text,
    job_number text,
    part_id uuid,
    part_name text,
    part_description text,
    part_quantity integer
)
LANGUAGE plpgsql
STABLE
AS $function$
BEGIN
    RETURN QUERY
    WITH eligible_jobs AS (
        SELECT j.id, j.job_number FROM jobs j
        WHERE j.company_id = p_company_id
          AND j.status IN ('not_started', 'in_progress')
    ),
    station_ops AS (
        SELECT jo.id, jo.job_id, jo.job_part_id, jo.operation_name, jo.status, jo.sequence, ej.job_number
        FROM job_operations jo
        JOIN eligible_jobs ej ON ej.id = jo.job_id
        WHERE jo.work_center_id = p_work_center_id
          AND jo.status IN ('pending', 'in_progress')
    ),
    ready_or_active AS (
        SELECT so.id, so.job_id, so.job_part_id, so.operation_name, so.status, so.job_number
        FROM station_ops so
        WHERE so.status = 'in_progress'
           OR NOT EXISTS (
               SELECT 1 FROM job_operations prev
               WHERE prev.job_part_id = so.job_part_id
                 AND prev.sequence < so.sequence
                 AND prev.status NOT IN ('completed', 'skipped')
           )
    )
    SELECT
        ra.job_id,
        ra.job_part_id,
        ra.id AS job_operation_id,
        ra.operation_name,
        ra.status AS op_status,
        ra.job_number,
        jp.part_id,
        p.part_name,
        p.description AS part_description,
        jp.quantity AS part_quantity
    FROM ready_or_active ra
    JOIN job_parts jp ON jp.id = ra.job_part_id
    JOIN parts p ON p.id = jp.part_id;
END;
$function$;

COMMENT ON FUNCTION public.get_ready_operations_for_station(uuid, uuid)
    IS 'Operator-station readiness query: returns ops at the given work_center that are ready (no incomplete predecessors in the same job_part) or currently in_progress, scoped to the company. Renamed from the earlier operation_type_id-based version when operation_types collapsed into work_centers.';

-- ----------------------------------------------------------------------------
-- 3.8 get_ready_operations_batch — alerts/dashboard summary
-- ----------------------------------------------------------------------------
--
-- Same shape as before; doesn't reference work_center_id directly so the body
-- is unchanged. Recreated only because the function was dropped via CASCADE
-- in Phase 1 (operator_sessions FK chain).

CREATE OR REPLACE FUNCTION public.get_ready_operations_batch(p_job_ids uuid[])
RETURNS TABLE (
    job_id uuid,
    operation_name text,
    ready_count integer
)
LANGUAGE plpgsql
STABLE
AS $function$
BEGIN
    RETURN QUERY
    WITH
    in_progress_ops AS (
        SELECT jo.job_id, jo.operation_name, COUNT(*)::integer AS cnt
        FROM job_operations jo
        WHERE jo.job_id = ANY(p_job_ids)
          AND jo.status = 'in_progress'
        GROUP BY jo.job_id, jo.operation_name
    ),
    jobs_with_in_progress AS (
        SELECT DISTINCT ip.job_id FROM in_progress_ops ip
    ),
    ready_ops AS (
        SELECT jo.job_id, jo.operation_name
        FROM job_operations jo
        WHERE jo.job_id = ANY(p_job_ids)
          AND jo.job_id NOT IN (SELECT jwi.job_id FROM jobs_with_in_progress jwi)
          AND jo.status = 'pending'
          AND NOT EXISTS (
              SELECT 1 FROM job_operations prev
              WHERE prev.job_part_id = jo.job_part_id
                AND prev.sequence < jo.sequence
                AND prev.status NOT IN ('completed', 'skipped')
          )
    ),
    ready_agg AS (
        SELECT ro.job_id, MIN(ro.operation_name) AS operation_name, COUNT(*)::integer AS ready_count
        FROM ready_ops ro
        GROUP BY ro.job_id
    )
    SELECT ip.job_id, ip.operation_name, ip.cnt AS ready_count
    FROM in_progress_ops ip
    UNION ALL
    SELECT ra.job_id, ra.operation_name, ra.ready_count
    FROM ready_agg ra;
END;
$function$;

COMMENT ON FUNCTION public.get_ready_operations_batch(uuid[])
    IS 'Returns per-job summary of ready or in-progress operations across the given job IDs. Used by alerts/dashboard. Body unchanged from the prior version (does not reference renamed columns).';

-- ============================================================================
-- Phase 4: Rewrite demo_data_templates to a minimal known-good seed
-- ============================================================================
--
-- The active demo template predates this migration (parts split into two
-- tables, operation_types instead of work_centers, routing_materials instead
-- of parts_bom). Mechanically transforming the existing template_data jsonb
-- in SQL is feasible but produces a brittle one-off transform and a demo
-- dataset that's still anemic against the new schema.
--
-- Instead: per the plan ("template reset to minimal seed; expand in PR 3
-- alongside UI"), we replace the active template_data with a small known-good
-- seed exercising the new shape:
--   - 1 vendor (used by an external work_center)
--   - 2 work_centers (1 internal, 1 external)
--   - 3 parts (1 raw material is_stockable, 1 sub-assembly both flags, 1
--     finished part is_manufacturable only)
--   - 1 routing on the finished part with 1 internal op
--   - 1 parts_bom edge (finished_part consumes sub-assembly)
--
-- The customers / quotes / jobs sections are dropped from the template; PR 3
-- will re-author the full template alongside the new UI work. The
-- seed_demo_data, reset_demo_company, and create_demo_company functions are
-- DROPPED in Phase 1 (not left broken); PR 3 rebuilds them against the new
-- schema. Demo seeding is unavailable until then — call create_demo_company
-- after PR 1 merges and you'll get an "function does not exist" error, which
-- is the intended behavior.

UPDATE public.demo_data_templates
   SET template_data = jsonb_build_object(
        'note', 'Minimal seed for PR 1 of unify-parts-inventory-add-work-centers-vendors. Expand in PR 3 alongside the UI rewrite. seed_demo_data() is also being rewritten in PR 3; this template is intentionally narrow until then.',
        'vendors', jsonb_build_array(
            jsonb_build_object(
                '_ref', 'vendor_outside_coating',
                'name', 'Acme Coating',
                'contact_email', 'orders@acmecoating.example.com'
            )
        ),
        'work_centers', jsonb_build_array(
            jsonb_build_object(
                '_ref', 'wc_lathe',
                'name', 'Mazak Lathe',
                'kind', 'internal',
                'labor_rate', 95.00,
                'description', 'Internal turning cell'
            ),
            jsonb_build_object(
                '_ref', 'wc_coating',
                'name', 'Acme Coating (outside)',
                'kind', 'external',
                'vendor_ref', 'vendor_outside_coating',
                'description', 'Outside coating partner'
            )
        ),
        'parts', jsonb_build_array(
            jsonb_build_object(
                '_ref', 'part_raw_bar',
                'part_name', '1018-BAR',
                'description', '1018 cold-rolled steel bar, 1in dia',
                'is_manufacturable', false,
                'is_stockable', true,
                'primary_unit', 'in',
                'quantity', 240,
                'cost_per_unit', 0.85,
                'reorder_point', 60
            ),
            jsonb_build_object(
                '_ref', 'part_sub_assembly',
                'part_name', 'SUB-001',
                'description', 'Turned blank used in finished part',
                'is_manufacturable', true,
                'is_stockable', true,
                'primary_unit', 'each',
                'quantity', 0
            ),
            jsonb_build_object(
                '_ref', 'part_finished',
                'part_name', 'WIDGET-100',
                'description', 'Finished widget',
                'is_manufacturable', true,
                'is_stockable', false
            )
        ),
        'routings', jsonb_build_array(
            jsonb_build_object(
                '_ref', 'routing_widget',
                'part_ref', 'part_finished',
                'name', 'WIDGET-100 routing',
                'operations', jsonb_build_array(
                    jsonb_build_object(
                        '_ref', 'op_widget_turn',
                        'work_center_ref', 'wc_lathe',
                        'sequence', 10,
                        'setup_minutes', 30,
                        'cycle_minutes_per_unit', 4.5
                    )
                )
            )
        ),
        'parts_bom', jsonb_build_array(
            jsonb_build_object(
                'parent_ref', 'part_finished',
                'child_ref', 'part_sub_assembly',
                'quantity', 1,
                'unit', 'each'
            )
        )
   )
 WHERE is_active = true;

-- ============================================================================
-- Phase 5: Restore operator_sessions FKs against the new tables
-- ============================================================================
--
-- operator_sessions previously had:
--   operation_type_id uuid NOT NULL  → operation_types(id) ON DELETE RESTRICT
--   job_operation_id  uuid           → job_operations(id)  ON DELETE SET NULL
--
-- Both target tables were just dropped + recreated (operation_types is fully
-- replaced by work_centers; job_operations is recreated). We need to:
--   1. Rename the column operation_type_id → work_center_id
--   2. Add the new FK against work_centers(id) ON DELETE RESTRICT
--   3. Re-add the FK on job_operation_id against the new job_operations
--
-- The FKs from operator_sessions were dropped automatically by the CASCADE on
-- the drops in Phase 1 (Postgres drops dependent constraints, not the parent
-- column). The column itself survives.

ALTER TABLE public.operator_sessions
    RENAME COLUMN operation_type_id TO work_center_id;

ALTER TABLE public.operator_sessions
    ADD CONSTRAINT operator_sessions_work_center_id_fkey
    FOREIGN KEY (work_center_id) REFERENCES public.work_centers(id) ON DELETE RESTRICT;

ALTER TABLE public.operator_sessions
    ADD CONSTRAINT operator_sessions_job_operation_id_fkey
    FOREIGN KEY (job_operation_id) REFERENCES public.job_operations(id) ON DELETE SET NULL;

-- The job_id FK on operator_sessions also pointed at the old jobs table.
-- The CASCADE drop removed the constraint; re-add it against the new jobs.
ALTER TABLE public.operator_sessions
    ADD CONSTRAINT operator_sessions_job_id_fkey
    FOREIGN KEY (job_id) REFERENCES public.jobs(id) ON DELETE CASCADE;

COMMENT ON COLUMN public.operator_sessions.work_center_id IS 'FK to the work_center this session ran at (renamed from operation_type_id when operation_types was replaced by work_centers).';

-- ============================================================================
-- Phase 6: Grant SELECT on every recreated table to jigged_ai_readonly
-- ============================================================================
--
-- The role + USAGE on schema public are granted in 20260313_fix_ai_readonly_rls
-- and survive this migration. We only need to grant SELECT on the new tables;
-- the ai_readonly_select RLS policies above gate visibility per company.

GRANT SELECT ON
    public.vendors,
    public.parts,
    public.parts_unit_conversions,
    public.parts_bom,
    public.inventory_transactions,
    public.work_centers,
    public.routings,
    public.routing_operations,
    public.quotes,
    public.quote_line_items,
    public.quote_materials,
    public.quote_operations,
    public.part_pricing_tiers,
    public.jobs,
    public.job_parts,
    public.job_operations,
    public.job_materials
TO jigged_ai_readonly;

COMMIT;

-- ############################################################################
-- END MIGRATION: 20260502_unify_parts_inventory_add_work_centers_vendors.sql
-- ############################################################################


-- ############################################################################
-- BEGIN MIGRATION: 20260504_part_procurement_tiers.sql
-- ############################################################################

-- ============================================================================
-- Procurement tier sheets for bought parts (Phase 1)
-- ============================================================================
--
-- Context. Iteration 2 usability review showed that bought parts often have
-- vendor-supplied tiered pricing ("buy 100 lbs at $0.85/lb, buy 1000 lbs at
-- $0.75/lb"). The single `parts.cost_per_unit` column can't represent that
-- shape. This migration adds an optional `part_procurement_tiers` table that
-- holds the tier sheets, and a `get_procurement_cost(part_id, qty)` SQL
-- function that resolves the right cost for a given quantity.
--
-- Phase 1 scope (this migration + chunk 13 UI):
--   - Data model + tier-sheet UI on bought-part detail pages.
--   - recalculate_part_cost is patched to call get_procurement_cost(child, 1)
--     for BOM rollups so that bought children with tiers contribute the
--     smallest-tier cost rather than the snapshot-only cost_per_unit.
--   - parts.cost_per_unit stays as the single/default cost for bought parts
--     (used as the fallback when no tier matches and as the snapshot for
--     made parts).
--
-- Phase 2 (deferred): tier-aware quote-time recomputation that walks the
-- BOM with the aggregate quote quantity. Tracked in the iteration-2 plan's
-- "Risks and known follow-ups" section.
--
-- Note on `sequence`: there is intentionally no `sequence` column on the
-- tier table. Tier ordering derives from `min_quantity` ascending — that
-- IS the order, and a separate sequence column would just be a second
-- source of truth that can drift. The unique constraint on
-- (part_id, vendor_id, min_quantity) ensures no two tiers from the same
-- vendor sit at the same break.
--
-- Forward-only. Single BEGIN/COMMIT.

BEGIN;

-- ============================================================================
-- Phase 1: part_procurement_tiers table
-- ============================================================================

CREATE TABLE public.part_procurement_tiers (
    id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    part_id uuid NOT NULL REFERENCES public.parts(id) ON DELETE CASCADE,
    vendor_id uuid REFERENCES public.vendors(id) ON DELETE RESTRICT,
    -- Nullable vendor_id = "internal estimate, no specific vendor yet"
    -- (useful when sketching cost before sourcing).
    min_quantity numeric NOT NULL CHECK (min_quantity > 0),
    cost_per_unit numeric NOT NULL CHECK (cost_per_unit > 0),
    quoted_at date,
    expires_at date,
    notes text,
    created_at timestamptz NOT NULL DEFAULT now(),
    updated_at timestamptz NOT NULL DEFAULT now(),
    -- Tier ordering is derived from min_quantity ascending. We do NOT carry
    -- a separate `sequence` column — that would be a second source of truth
    -- that can drift from the min_quantity ordering. The unique constraint
    -- below ensures no two tiers from the same vendor sit at the same break.
    UNIQUE (part_id, vendor_id, min_quantity)
);

CREATE INDEX idx_procurement_tiers_part
    ON public.part_procurement_tiers (part_id);

CREATE INDEX idx_procurement_tiers_vendor
    ON public.part_procurement_tiers (vendor_id) WHERE vendor_id IS NOT NULL;

CREATE INDEX idx_procurement_tiers_expiring
    ON public.part_procurement_tiers (part_id, expires_at) WHERE expires_at IS NOT NULL;

COMMENT ON TABLE public.part_procurement_tiers
    IS 'Vendor-keyed tiered pricing for bought parts. Each row is one (vendor, min_quantity, cost_per_unit) point on a vendor''s tier sheet. vendor_id may be NULL for "internal estimate" rows. Ordering of tiers within a vendor sheet is derived from min_quantity ASC — no separate sequence column. Resolved at read time via get_procurement_cost(part_id, qty), which picks the cheapest non-expired tier where min_quantity <= qty across all vendors.';

COMMENT ON COLUMN public.part_procurement_tiers.vendor_id
    IS 'Vendor offering this tier. NULL = "internal estimate" (sketch before sourcing). When set, ON DELETE RESTRICT prevents removing a vendor that still has live tier sheets — drop the tiers first.';

COMMENT ON COLUMN public.part_procurement_tiers.min_quantity
    IS 'Lower bound (inclusive) of this tier in the part''s primary unit. A row with min_quantity=100 means "this price applies when ordering >= 100 of this part". Combined with the next-larger tier from the same vendor, defines a half-open break range.';

COMMENT ON COLUMN public.part_procurement_tiers.cost_per_unit
    IS 'Per-primary_unit cost at this tier. Always positive (CHECK).';

COMMENT ON COLUMN public.part_procurement_tiers.expires_at
    IS 'Date when this tier expires. Tiers past their expires_at are excluded by get_procurement_cost. NULL = never expires (open-ended quote).';


-- ============================================================================
-- Phase 2: updated_at trigger
-- ============================================================================

CREATE TRIGGER part_procurement_tiers_updated_at
    BEFORE UPDATE ON public.part_procurement_tiers
    FOR EACH ROW
    EXECUTE FUNCTION public.update_updated_at_column();


-- ============================================================================
-- Phase 3: RLS policies — mirror parts_bom (scope through parts.company_id)
-- ============================================================================
--
-- part_procurement_tiers has no company_id of its own (the part_id FK
-- carries the tenancy). RLS pivots through `parts` exactly the way parts_bom
-- does, so the same get_user_company_ids() helper enforces multi-tenant
-- isolation here.

ALTER TABLE public.part_procurement_tiers ENABLE ROW LEVEL SECURITY;

CREATE POLICY "Users can view part_procurement_tiers"
    ON public.part_procurement_tiers
    FOR SELECT
    USING (part_id IN (
        SELECT parts.id
        FROM public.parts
        WHERE parts.company_id IN (SELECT get_user_company_ids() AS get_user_company_ids)
    ));

CREATE POLICY "Users can insert part_procurement_tiers"
    ON public.part_procurement_tiers
    FOR INSERT
    WITH CHECK (part_id IN (
        SELECT parts.id
        FROM public.parts
        WHERE parts.company_id IN (SELECT get_user_company_ids() AS get_user_company_ids)
    ));

CREATE POLICY "Users can update part_procurement_tiers"
    ON public.part_procurement_tiers
    FOR UPDATE
    USING (part_id IN (
        SELECT parts.id
        FROM public.parts
        WHERE parts.company_id IN (SELECT get_user_company_ids() AS get_user_company_ids)
    ));

CREATE POLICY "Users can delete part_procurement_tiers"
    ON public.part_procurement_tiers
    FOR DELETE
    USING (part_id IN (
        SELECT parts.id
        FROM public.parts
        WHERE parts.company_id IN (SELECT get_user_company_ids() AS get_user_company_ids)
    ));

CREATE POLICY "ai_readonly_select"
    ON public.part_procurement_tiers
    FOR SELECT
    TO jigged_ai_readonly
    USING (EXISTS (
        SELECT 1
        FROM public.parts
        WHERE parts.id = part_procurement_tiers.part_id
          AND parts.company_id = (current_setting('jigged.company_id'::text, true))::uuid
    ));


-- ============================================================================
-- Phase 4: get_procurement_cost(part_id, qty) function
-- ============================================================================
--
-- Contract (verbatim — see the COMMENT below; callers MUST NOT add a
-- "is this a bought part" guard before invoking):
--
-- - Bought parts WITH tiers: cheapest non-expired tier where
--   min_quantity <= p_qty across vendors. Returns source='tier'.
-- - Bought parts WITHOUT tiers: parts.cost_per_unit. Returns 'fallback'.
-- - Made parts (sub-assemblies and pure custom): no tiers will match
--   (they wouldn't have any), so returns parts.cost_per_unit which is
--   the snapshot from the most recent recalculate_part_cost call.
--   vendor_id and tier_id are NULL in this case. source='fallback'.
--
-- "Non-expired" = expires_at IS NULL OR expires_at >= CURRENT_DATE.
--
-- "Cheapest" tie-break: ORDER BY cost_per_unit ASC, then min_quantity DESC
-- (prefer the wider/larger break at the same price), then vendor_id NULLS
-- LAST (prefer a real vendor over an internal estimate at the same price).

CREATE OR REPLACE FUNCTION public.get_procurement_cost(p_part_id uuid, p_qty numeric)
 RETURNS TABLE(unit_cost numeric, vendor_id uuid, tier_id uuid, source text)
 LANGUAGE plpgsql
 STABLE
AS $function$
DECLARE
    v_tier RECORD;
    v_fallback numeric;
BEGIN
    -- Pick the cheapest non-expired tier across vendors where the requested
    -- quantity meets or exceeds the tier's min_quantity break.
    SELECT t.id, t.cost_per_unit, t.vendor_id
      INTO v_tier
      FROM public.part_procurement_tiers t
     WHERE t.part_id = p_part_id
       AND t.min_quantity <= p_qty
       AND (t.expires_at IS NULL OR t.expires_at >= CURRENT_DATE)
     ORDER BY t.cost_per_unit ASC,
              t.min_quantity DESC,
              -- Prefer a real vendor over an "internal estimate" tie.
              t.vendor_id NULLS LAST
     LIMIT 1;

    IF FOUND THEN
        unit_cost := v_tier.cost_per_unit;
        vendor_id := v_tier.vendor_id;
        tier_id := v_tier.id;
        source := 'tier';
        RETURN NEXT;
        RETURN;
    END IF;

    -- No matching tier — fall back to the part's snapshot cost. This branch
    -- intentionally fires for:
    --   - bought parts with no tier sheet at all
    --   - bought parts whose tier sheets all start above p_qty
    --   - bought parts whose tier sheets are all expired
    --   - made parts (which never have tier sheets; cost_per_unit is the
    --     recalculate_part_cost snapshot)
    SELECT cost_per_unit INTO v_fallback FROM public.parts WHERE id = p_part_id;

    unit_cost := v_fallback;
    vendor_id := NULL;
    tier_id := NULL;
    source := 'fallback';
    RETURN NEXT;
END;
$function$;

COMMENT ON FUNCTION public.get_procurement_cost(uuid, numeric)
    IS 'Resolve the per-unit procurement cost of a part for a target quantity. Contract (works for ANY part, not just bought parts): bought parts with tiers return the cheapest non-expired tier where min_quantity <= p_qty (source=''tier''); bought parts without a matching tier return parts.cost_per_unit (source=''fallback''); made parts (no tier sheets) return parts.cost_per_unit which is the snapshot from the most recent recalculate_part_cost call (source=''fallback''). Callers MUST NOT add a "is this a bought part" guard — the function handles all part kinds correctly. Used by the BOM-rollup branch of recalculate_part_cost (with qty=1 in Phase 1) and by the procurement-pricing UI status line.';


-- ============================================================================
-- Phase 5: Patch recalculate_part_cost to use get_procurement_cost for BOM
-- ============================================================================
--
-- Identical to the chunk-11 version EXCEPT the BOM-rollup loop now reads the
-- child's effective cost via get_procurement_cost(child_id, 1) instead of
-- pulling child.cost_per_unit directly. Per get_procurement_cost's
-- documented contract, this works for any child kind:
--   - bought child with tiers → smallest-tier cost
--   - bought child without tiers → child.cost_per_unit (fallback)
--   - made child → child.cost_per_unit snapshot (fallback)
--
-- No type-of-child guard is needed at the call site. Phase 1 still uses
-- qty=1 — the tier-aware aggregate-quantity rollup is Phase 2.

CREATE OR REPLACE FUNCTION public.recalculate_part_cost(p_part_id uuid)
 RETURNS numeric
 LANGUAGE plpgsql
AS $function$
DECLARE
    v_source text;
    v_routing_id uuid;
    v_total_cost numeric := 0;
    v_op record;
    v_op_cost numeric;
    v_bom record;
    v_to_primary_factor numeric;
    v_qty_in_primary_unit numeric;
    v_child_unit_cost numeric;
BEGIN
    SELECT source INTO v_source FROM parts WHERE id = p_part_id;
    IF v_source IS NULL THEN
        RAISE EXCEPTION 'part % not found', p_part_id;
    END IF;
    IF v_source <> 'made' THEN
        -- Bought parts: cost is the procurement cost; no rollup to compute.
        RETURN (SELECT cost_per_unit FROM parts WHERE id = p_part_id);
    END IF;

    SELECT id INTO v_routing_id FROM routings WHERE part_id = p_part_id;

    -- Routing operations (only if a routing exists; some made parts may not
    -- have one yet, e.g. immediately after creation).
    IF v_routing_id IS NOT NULL THEN
        FOR v_op IN
            SELECT ro.setup_minutes,
                   ro.cycle_minutes_per_unit,
                   ro.labor_rate_override,
                   ro.external_unit_price,
                   ro.external_setup_cost,
                   wc.kind AS wc_kind,
                   wc.labor_rate AS wc_labor_rate
            FROM routing_operations ro
            JOIN work_centers wc ON wc.id = ro.work_center_id
            WHERE ro.routing_id = v_routing_id
        LOOP
            IF v_op.wc_kind = 'internal' THEN
                -- Per the no-silent-fallbacks engineering principle: if neither
                -- the per-op override nor the work-center default rate is set,
                -- we cannot price this operation. Raise rather than silently
                -- treating as $0 cost (which would let users quote at zero
                -- labor without ever seeing the missing data).
                IF v_op.labor_rate_override IS NULL AND v_op.wc_labor_rate IS NULL THEN
                    RAISE EXCEPTION 'Cannot recalculate cost for part %: routing op has no labor rate (neither override nor work_center default)', p_part_id
                        USING ERRCODE = 'check_violation';
                END IF;
                v_op_cost := (COALESCE(v_op.setup_minutes, 0) / 1
                               + COALESCE(v_op.cycle_minutes_per_unit, 0))
                             * COALESCE(v_op.labor_rate_override, v_op.wc_labor_rate)
                             / 60.0;
            ELSE
                -- External op: at least one of unit_price or setup_cost should be
                -- set (a free outside op is meaningless). NULL on both means
                -- the user hasn't filled in pricing yet — refuse to compute.
                IF v_op.external_unit_price IS NULL AND v_op.external_setup_cost IS NULL THEN
                    RAISE EXCEPTION 'Cannot recalculate cost for part %: external routing op has no pricing (neither external_unit_price nor external_setup_cost)', p_part_id
                        USING ERRCODE = 'check_violation';
                END IF;
                v_op_cost := COALESCE(v_op.external_unit_price, 0)
                             + COALESCE(v_op.external_setup_cost, 0) / 1;
            END IF;
            v_total_cost := v_total_cost + v_op_cost;
        END LOOP;
    END IF;

    -- BOM children. Convert BOM unit → child.primary_unit if they differ;
    -- error explicitly when no conversion exists (matches the existing
    -- unknown_* validation pattern).
    --
    -- Child unit cost is resolved through get_procurement_cost(child_id, 1)
    -- per the function's documented contract — this works for any child
    -- kind (bought-with-tiers, bought-without-tiers, made-snapshot). No
    -- caller-side guard needed. Phase 1 uses qty=1; Phase 2 will revisit
    -- to enable tier-aware aggregate-quantity rollups at quote time.
    FOR v_bom IN
        SELECT b.quantity, b.unit, b.child_part_id,
               c.primary_unit AS child_primary_unit
        FROM parts_bom b
        JOIN parts c ON c.id = b.child_part_id
        WHERE b.parent_part_id = p_part_id
    LOOP
        SELECT unit_cost
          INTO v_child_unit_cost
          FROM public.get_procurement_cost(v_bom.child_part_id, 1);

        IF v_child_unit_cost IS NULL THEN
            -- Per the no-silent-fallbacks principle: a BOM child without a
            -- cost can't contribute to the parent's cost rollup. Raise rather
            -- than treating as $0 (which would let users quote without ever
            -- noticing the missing child cost). The UI should walk the BOM
            -- bottom-up and refuse to recalc the parent until all leaves are
            -- priced.
            RAISE EXCEPTION 'Cannot recalculate cost for part %: BOM child % has no cost_per_unit (recalc the child first, or add a procurement tier)', p_part_id, v_bom.child_part_id
                USING ERRCODE = 'check_violation';
        END IF;

        IF v_bom.unit IS DISTINCT FROM v_bom.child_primary_unit THEN
            SELECT to_primary_factor INTO v_to_primary_factor
            FROM parts_unit_conversions
            WHERE part_id = v_bom.child_part_id
              AND from_unit = v_bom.unit;

            IF v_to_primary_factor IS NULL THEN
                RAISE EXCEPTION 'No unit conversion from % to % for part %',
                    v_bom.unit, v_bom.child_primary_unit, v_bom.child_part_id
                    USING ERRCODE = 'check_violation';
            END IF;

            v_qty_in_primary_unit := v_bom.quantity * v_to_primary_factor;
        ELSE
            v_qty_in_primary_unit := v_bom.quantity;
        END IF;

        v_total_cost := v_total_cost + v_qty_in_primary_unit * v_child_unit_cost;
    END LOOP;

    UPDATE parts
    SET cost_per_unit = v_total_cost,
        cost_recalculated_at = now()
    WHERE id = p_part_id;

    RETURN v_total_cost;
END;
$function$;

COMMENT ON FUNCTION public.recalculate_part_cost(uuid)
    IS 'Recompute and snapshot the unit cost of a made part (source=''made'') by walking its routing operations + BOM children. Bought parts (source=''bought'') return parts.cost_per_unit unchanged. BOM child unit costs are resolved through get_procurement_cost(child_id, 1) per its documented all-kinds contract — bought children with live tiers contribute the smallest-tier cost, bought children without tiers and made children both contribute their parts.cost_per_unit snapshot. Raises on missing labor rate, missing external pricing, missing child cost, or missing unit conversion — never silently substitutes $0. Updates parts.cost_per_unit and parts.cost_recalculated_at on success.';


COMMIT;

-- ############################################################################
-- END MIGRATION: 20260504_part_procurement_tiers.sql
-- ############################################################################


-- ############################################################################
-- BEGIN MIGRATION: 20260504_part_source_enum_and_stocked_rename.sql
-- ############################################################################

-- ============================================================================
-- Pivot parts classification: source enum + is_stocked rename
-- ============================================================================
--
-- Context. Iteration 1 (PR #246) shipped two booleans on parts:
-- (is_manufacturable, is_stockable). Usability review showed the (false,false)
-- "orphan" quadrant is a phantom state that confuses the form (no chip applies)
-- and the dropdown ("Manufactured" vs "Inventory" obscures the made-vs-bought
-- distinction). The fix is to replace `is_manufacturable boolean` with a
-- `source text` enum ('made' | 'bought') and rename `is_stockable` →
-- `is_stocked` to match shop-floor language ("Is this stocked?").
--
-- Backfill rule:
--   source = CASE
--       WHEN is_manufacturable THEN 'made'
--       WHEN is_stockable      THEN 'bought'
--       ELSE 'made'  -- the (false, false) orphan default
--   END
--
-- The orphan default is 'made' (NOT 'bought') because Contour's analysis showed
-- their 689 (false, false) rows are unshipped customer parts (quoted but not
-- yet built), not procurement items. Defaulting these to 'bought' would have
-- silently re-classified them as drop-ship/service items and surfaced
-- "Service" chips on the parts list, which is wrong. Rolling them into 'made'
-- (combined with !is_stocked) classifies them as "Custom Made" — a faithful
-- description of an unshipped customer part.
--
-- After this migration, every part lives in exactly one of four valid quadrants:
--   (source=made,   !is_stocked)  → Custom Made
--   (source=made,    is_stocked)  → Sub-assembly
--   (source=bought,  is_stocked)  → Raw Material
--   (source=bought, !is_stocked)  → Service / Drop-ship
--
-- This migration also:
--   - Renames the parts_stockable_requires_unit constraint to ..._stocked_...
--   - Replaces the partial indexes that filtered by the old columns
--   - Rewrites recalculate_part_cost to read source = 'made' instead of
--     is_manufacturable. (NOTE: recalculate_part_cost still reads
--     child.cost_per_unit directly for BOM children — chunk 13 will rewrite
--     that to call get_procurement_cost. Don't pre-do that work here.)
--   - Rewrites seed_demo_data to read 'source' / 'is_stocked' from the
--     template_data jsonb keys
--   - Rewrites demo_data_templates.template_data parts entries to use the
--     new keys (source, is_stocked) instead of (is_manufacturable, is_stockable)
--
-- Forward-only. Single BEGIN/COMMIT.

BEGIN;

-- ============================================================================
-- Phase 1: Add `source` column with backfill, drop `is_manufacturable`
-- ============================================================================

ALTER TABLE public.parts
    ADD COLUMN source text NOT NULL DEFAULT 'made'
    CHECK (source IN ('made', 'bought'));

-- Backfill: orphan (false, false) defaults to 'made' (see header comment).
UPDATE public.parts
   SET source = CASE
       WHEN is_manufacturable THEN 'made'
       WHEN is_stockable      THEN 'bought'
       ELSE 'made'
   END;

ALTER TABLE public.parts DROP COLUMN is_manufacturable;

COMMENT ON COLUMN public.parts.source
    IS 'How this part is sourced. ''made'' = produced in-shop (will have a routing); ''bought'' = procured from a vendor. Combined with is_stocked, classifies the part into one of four quadrants (Custom Made / Sub-assembly / Raw Material / Service+Drop-ship). Replaces the prior is_manufacturable boolean — see the 20260504 migration header for the (false,false)→''made'' orphan-default rationale.';


-- ============================================================================
-- Phase 2: Rename is_stockable → is_stocked
-- ============================================================================
--
-- "Is this stocked?" matches shop-floor language better than "Is this
-- stockable?" (the latter sounds like a capability, not a state). Form
-- labels follow.

ALTER TABLE public.parts RENAME COLUMN is_stockable TO is_stocked;

ALTER TABLE public.parts
    RENAME CONSTRAINT parts_stockable_requires_unit
        TO parts_stocked_requires_unit;

COMMENT ON COLUMN public.parts.is_stocked
    IS 'True if quantities of this part are tracked in inventory (renamed from is_stockable in the 20260504 migration to match shop-floor language). Used for the "Stocked" saved view, the inventory panel on the part detail page, and the reorder alerts query.';

COMMENT ON COLUMN public.parts.primary_unit
    IS 'Canonical unit of the on-hand quantity and the cost_per_unit. Required when is_stocked=true (parts_stocked_requires_unit CHECK); may be NULL for made-only parts.';

COMMENT ON COLUMN public.parts.cost_per_unit
    IS 'Per-primary_unit cost. For bought items (source=''bought''), the procurement cost. For made items (source=''made''), snapshot from the most recent recalculate_part_cost call.';


-- ============================================================================
-- Phase 3: Replace partial indexes
-- ============================================================================
--
-- The old indexes filtered on the dropped/renamed columns. Recreate them
-- against the new column names so the parts list page's view filters
-- ("Made", "Stocked") still hit an index.

DROP INDEX IF EXISTS public.idx_parts_company_manufacturable;
DROP INDEX IF EXISTS public.idx_parts_company_stockable;

CREATE INDEX IF NOT EXISTS idx_parts_company_made
    ON public.parts (company_id) WHERE source = 'made';

CREATE INDEX IF NOT EXISTS idx_parts_company_stocked
    ON public.parts (company_id) WHERE is_stocked;


-- ============================================================================
-- Phase 4: Rewrite recalculate_part_cost to read `source = 'made'`
-- ============================================================================
--
-- Functionally identical to the prior version except:
--   - reads parts.source instead of parts.is_manufacturable
--   - the gating condition becomes `source <> 'made'` (i.e. a bought part
--     returns its current cost_per_unit unchanged)
--
-- IMPORTANT: this function still reads child.cost_per_unit directly for BOM
-- children. Chunk 13 will rewrite that branch to call get_procurement_cost
-- once the procurement_tiers table exists. Do NOT pre-do that work here —
-- this migration is only the source-enum rename.

CREATE OR REPLACE FUNCTION public.recalculate_part_cost(p_part_id uuid)
 RETURNS numeric
 LANGUAGE plpgsql
AS $function$
DECLARE
    v_source text;
    v_routing_id uuid;
    v_total_cost numeric := 0;
    v_op record;
    v_op_cost numeric;
    v_bom record;
    v_to_primary_factor numeric;
    v_qty_in_primary_unit numeric;
BEGIN
    SELECT source INTO v_source FROM parts WHERE id = p_part_id;
    IF v_source IS NULL THEN
        RAISE EXCEPTION 'part % not found', p_part_id;
    END IF;
    IF v_source <> 'made' THEN
        -- Bought parts: cost is the procurement cost; no rollup to compute.
        RETURN (SELECT cost_per_unit FROM parts WHERE id = p_part_id);
    END IF;

    SELECT id INTO v_routing_id FROM routings WHERE part_id = p_part_id;

    -- Routing operations (only if a routing exists; some made parts may not
    -- have one yet, e.g. immediately after creation).
    IF v_routing_id IS NOT NULL THEN
        FOR v_op IN
            SELECT ro.setup_minutes,
                   ro.cycle_minutes_per_unit,
                   ro.labor_rate_override,
                   ro.external_unit_price,
                   ro.external_setup_cost,
                   wc.kind AS wc_kind,
                   wc.labor_rate AS wc_labor_rate
            FROM routing_operations ro
            JOIN work_centers wc ON wc.id = ro.work_center_id
            WHERE ro.routing_id = v_routing_id
        LOOP
            IF v_op.wc_kind = 'internal' THEN
                -- Per the no-silent-fallbacks engineering principle: if neither
                -- the per-op override nor the work-center default rate is set,
                -- we cannot price this operation. Raise rather than silently
                -- treating as $0 cost (which would let users quote at zero
                -- labor without ever seeing the missing data).
                IF v_op.labor_rate_override IS NULL AND v_op.wc_labor_rate IS NULL THEN
                    RAISE EXCEPTION 'Cannot recalculate cost for part %: routing op has no labor rate (neither override nor work_center default)', p_part_id
                        USING ERRCODE = 'check_violation';
                END IF;
                v_op_cost := (COALESCE(v_op.setup_minutes, 0) / 1
                               + COALESCE(v_op.cycle_minutes_per_unit, 0))
                             * COALESCE(v_op.labor_rate_override, v_op.wc_labor_rate)
                             / 60.0;
            ELSE
                -- External op: at least one of unit_price or setup_cost should be
                -- set (a free outside op is meaningless). NULL on both means
                -- the user hasn't filled in pricing yet — refuse to compute.
                IF v_op.external_unit_price IS NULL AND v_op.external_setup_cost IS NULL THEN
                    RAISE EXCEPTION 'Cannot recalculate cost for part %: external routing op has no pricing (neither external_unit_price nor external_setup_cost)', p_part_id
                        USING ERRCODE = 'check_violation';
                END IF;
                v_op_cost := COALESCE(v_op.external_unit_price, 0)
                             + COALESCE(v_op.external_setup_cost, 0) / 1;
            END IF;
            v_total_cost := v_total_cost + v_op_cost;
        END LOOP;
    END IF;

    -- BOM children. Convert BOM unit → child.primary_unit if they differ;
    -- error explicitly when no conversion exists (matches the existing
    -- unknown_* validation pattern).
    --
    -- NOTE: chunk 13 will replace `child.cost_per_unit` with a call to
    -- get_procurement_cost(child_id, 1) to enable tier-aware costing.
    -- Leave the direct read in place for now.
    FOR v_bom IN
        SELECT b.quantity, b.unit, b.child_part_id,
               c.primary_unit AS child_primary_unit,
               c.cost_per_unit AS child_cost_per_unit
        FROM parts_bom b
        JOIN parts c ON c.id = b.child_part_id
        WHERE b.parent_part_id = p_part_id
    LOOP
        IF v_bom.child_cost_per_unit IS NULL THEN
            -- Per the no-silent-fallbacks principle: a BOM child without a
            -- cost can't contribute to the parent's cost rollup. Raise rather
            -- than treating as $0 (which would let users quote without ever
            -- noticing the missing child cost). The UI should walk the BOM
            -- bottom-up and refuse to recalc the parent until all leaves are
            -- priced.
            RAISE EXCEPTION 'Cannot recalculate cost for part %: BOM child % has no cost_per_unit (recalc the child first)', p_part_id, v_bom.child_part_id
                USING ERRCODE = 'check_violation';
        END IF;

        IF v_bom.unit IS DISTINCT FROM v_bom.child_primary_unit THEN
            SELECT to_primary_factor INTO v_to_primary_factor
            FROM parts_unit_conversions
            WHERE part_id = v_bom.child_part_id
              AND from_unit = v_bom.unit;

            IF v_to_primary_factor IS NULL THEN
                RAISE EXCEPTION 'No unit conversion from % to % for part %',
                    v_bom.unit, v_bom.child_primary_unit, v_bom.child_part_id
                    USING ERRCODE = 'check_violation';
            END IF;

            v_qty_in_primary_unit := v_bom.quantity * v_to_primary_factor;
        ELSE
            v_qty_in_primary_unit := v_bom.quantity;
        END IF;

        v_total_cost := v_total_cost + v_qty_in_primary_unit * v_bom.child_cost_per_unit;
    END LOOP;

    UPDATE parts
    SET cost_per_unit = v_total_cost,
        cost_recalculated_at = now()
    WHERE id = p_part_id;

    RETURN v_total_cost;
END;
$function$;

COMMENT ON FUNCTION public.recalculate_part_cost(uuid)
    IS 'Recompute and snapshot the unit cost of a made part (source=''made'') by walking its routing operations + BOM children. Bought parts (source=''bought'') return parts.cost_per_unit unchanged. Raises on missing labor rate, missing external pricing, missing child cost, or missing unit conversion — never silently substitutes $0. Updates parts.cost_per_unit and parts.cost_recalculated_at on success.';


-- ============================================================================
-- Phase 5: Replace demo_data_templates.template_data parts entries
-- ============================================================================
--
-- The 20260504_rebuild_demo_seed migration shipped a rich template with
-- (is_manufacturable, is_stockable) keys per part. Rewrite the parts array
-- to use the new (source, is_stocked) keys. Coverage targets unchanged:
--   - 2 raw stockables    (source=bought, is_stocked=true)  → Raw Material
--   - 2 sub-assemblies    (source=made,   is_stocked=true)  → Sub-assembly
--   - 3 finished mfg parts(source=made,   is_stocked=false) → Custom Made
--   - 1 reference/scratch (source=made,   is_stocked=false) → Custom Made
--     (the prior "unclassified" example is reclassified to Custom Made; the
--     orphan quadrant no longer exists in the new model)
--
-- Everything else in template_data (vendors, work_centers, parts_bom,
-- routings, customers, quotes, jobs) stays exactly as 20260504_rebuild_demo_seed
-- shipped it. Only the parts array changes.

UPDATE public.demo_data_templates
   SET template_data = jsonb_set(
        template_data,
        '{parts}',
        jsonb_build_array(
            -- Raw stockables (vendor-supplied bar stock + plate)
            jsonb_build_object(
                '_ref', 'part_raw_bar',
                'part_name', '1018-BAR-1IN',
                'description', '1018 cold-rolled steel bar, 1in dia',
                'source', 'bought',
                'is_stocked', true,
                'primary_unit', 'in',
                'quantity', 240,
                'cost_per_unit', 0.85,
                'reorder_point', 60,
                'preferred_vendor_ref', 'vendor_steel_supply'
            ),
            jsonb_build_object(
                '_ref', 'part_raw_plate',
                'part_name', '6061-PLATE-0.25',
                'description', '6061-T6 aluminum plate, 0.25in thick',
                'source', 'bought',
                'is_stocked', true,
                'primary_unit', 'sqin',
                'quantity', 1800,
                'cost_per_unit', 0.12,
                'reorder_point', 600,
                'preferred_vendor_ref', 'vendor_steel_supply'
            ),
            -- Sub-assemblies (made AND stocked — children for the finished
            -- parts below)
            jsonb_build_object(
                '_ref', 'part_sub_blank',
                'part_name', 'SUB-BLANK-001',
                'description', 'Turned blank, used in WIDGET-100',
                'source', 'made',
                'is_stocked', true,
                'primary_unit', 'each',
                'quantity', 18,
                'cost_per_unit', 6.50
            ),
            jsonb_build_object(
                '_ref', 'part_sub_bracket',
                'part_name', 'SUB-BRACKET-002',
                'description', 'Milled bracket sub-assy, used in BRACKET-300',
                'source', 'made',
                'is_stocked', true,
                'primary_unit', 'each',
                'quantity', 24,
                'cost_per_unit', 11.20
            ),
            -- Finished made parts (the ones that get quoted/jobbed)
            jsonb_build_object(
                '_ref', 'part_widget',
                'part_name', 'WIDGET-100',
                'description', 'Finished widget assembly',
                'source', 'made',
                'is_stocked', false
            ),
            jsonb_build_object(
                '_ref', 'part_bracket',
                'part_name', 'BRACKET-300',
                'description', 'Mounting bracket, anodized',
                'source', 'made',
                'is_stocked', false
            ),
            jsonb_build_object(
                '_ref', 'part_pin',
                'part_name', 'PIN-200',
                'description', 'Hardened pin with EDM keyway',
                'source', 'made',
                'is_stocked', false
            ),
            -- Reference/scratch part. Was "unclassified" in the prior
            -- template; under the new model this is just another Custom Made
            -- row (source=made, !is_stocked). The orphan quadrant no longer
            -- exists.
            jsonb_build_object(
                '_ref', 'part_misc',
                'part_name', 'MISC-NOTE-001',
                'description', 'Reference / scratch part, not stocked',
                'source', 'made',
                'is_stocked', false
            )
        ),
        true  -- create the key if missing (it always exists, defense in depth)
   )
 WHERE is_active = true;


-- ============================================================================
-- Phase 6: Rewrite seed_demo_data() to read the new template keys
-- ============================================================================
--
-- The function is otherwise identical to the version 20260504_rebuild_demo_seed
-- shipped — only the parts insert reads `source` / `is_stocked` from the
-- template_data jsonb instead of the old `is_manufacturable` / `is_stockable`
-- keys, and the INSERT column list switches accordingly.

CREATE OR REPLACE FUNCTION public.seed_demo_data(
    p_company_id uuid,
    p_user_id uuid,
    p_template_name text DEFAULT 'default'
)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
    v_template jsonb;
    v_ref_map jsonb := '{}'::jsonb;
    v_item jsonb;
    v_inner jsonb;
    v_new_id uuid;
    v_routing_id uuid;
    v_quote_id uuid;
    v_job_id uuid;
    v_job_part_id uuid;
    v_part_id uuid;
BEGIN
    SELECT template_data INTO v_template
    FROM demo_data_templates
    WHERE name = p_template_name AND is_active = true
    LIMIT 1;

    IF v_template IS NULL THEN
        RAISE EXCEPTION 'No active demo template found with name: %', p_template_name;
    END IF;

    -- ── Vendors ───────────────────────────────────────────────────────────
    IF v_template->'vendors' IS NOT NULL THEN
        FOR v_item IN SELECT * FROM jsonb_array_elements(v_template->'vendors') LOOP
            v_new_id := gen_random_uuid();
            v_ref_map := jsonb_set(v_ref_map, ARRAY[v_item->>'_ref'], to_jsonb(v_new_id::text));
            INSERT INTO vendors (id, company_id, name,
                                 contact_name, contact_email, contact_phone,
                                 address_line1, address_line2, city, state, postal_code, country,
                                 notes, legacy_id)
            VALUES (v_new_id, p_company_id, v_item->>'name',
                    v_item->>'contact_name', v_item->>'contact_email', v_item->>'contact_phone',
                    v_item->>'address_line1', v_item->>'address_line2',
                    v_item->>'city', v_item->>'state', v_item->>'postal_code',
                    COALESCE(v_item->>'country', 'USA'),
                    v_item->>'notes', v_item->>'legacy_id');
        END LOOP;
    END IF;

    -- ── Work centers ──────────────────────────────────────────────────────
    -- Resolves vendor_ref via the ref-map for external work_centers.
    -- The CHECK constraints on work_centers enforce internal/external ↔ vendor.
    IF v_template->'work_centers' IS NOT NULL THEN
        FOR v_item IN SELECT * FROM jsonb_array_elements(v_template->'work_centers') LOOP
            v_new_id := gen_random_uuid();
            v_ref_map := jsonb_set(v_ref_map, ARRAY[v_item->>'_ref'], to_jsonb(v_new_id::text));
            INSERT INTO work_centers (id, company_id, name, kind, vendor_id,
                                      labor_rate, description)
            VALUES (v_new_id, p_company_id,
                    v_item->>'name',
                    COALESCE(v_item->>'kind', 'internal'),
                    CASE WHEN v_item->>'vendor_ref' IS NOT NULL
                         THEN (v_ref_map->>(v_item->>'vendor_ref'))::uuid
                         ELSE NULL END,
                    NULLIF(v_item->>'labor_rate', '')::numeric,
                    v_item->>'description');
        END LOOP;
    END IF;

    -- ── Parts ─────────────────────────────────────────────────────────────
    -- Inserted before parts_bom so child refs resolve. preferred_vendor_ref
    -- resolves through the ref-map. Reads `source` / `is_stocked` from
    -- template_data (renamed from `is_manufacturable` / `is_stockable` in
    -- this migration).
    IF v_template->'parts' IS NOT NULL THEN
        FOR v_item IN SELECT * FROM jsonb_array_elements(v_template->'parts') LOOP
            v_new_id := gen_random_uuid();
            v_ref_map := jsonb_set(v_ref_map, ARRAY[v_item->>'_ref'], to_jsonb(v_new_id::text));
            INSERT INTO parts (id, company_id, part_name, description,
                               source, is_stocked,
                               primary_unit, quantity, cost_per_unit,
                               reorder_point, preferred_vendor_id, legacy_id)
            VALUES (v_new_id, p_company_id,
                    v_item->>'part_name', v_item->>'description',
                    COALESCE(v_item->>'source', 'made'),
                    COALESCE((v_item->>'is_stocked')::boolean, false),
                    v_item->>'primary_unit',
                    COALESCE((v_item->>'quantity')::numeric, 0),
                    NULLIF(v_item->>'cost_per_unit', '')::numeric,
                    NULLIF(v_item->>'reorder_point', '')::numeric,
                    CASE WHEN v_item->>'preferred_vendor_ref' IS NOT NULL
                         THEN (v_ref_map->>(v_item->>'preferred_vendor_ref'))::uuid
                         ELSE NULL END,
                    v_item->>'legacy_id');
        END LOOP;
    END IF;

    -- ── parts_bom edges ───────────────────────────────────────────────────
    -- Both parent and child must already be in the ref-map (parts loop above).
    -- The enforce_no_bom_cycles trigger guards against accidental cycles in
    -- the template data — if the template defines one, this insert raises.
    IF v_template->'parts_bom' IS NOT NULL THEN
        FOR v_item IN SELECT * FROM jsonb_array_elements(v_template->'parts_bom') LOOP
            INSERT INTO parts_bom (parent_part_id, child_part_id, quantity, unit, sequence, notes)
            VALUES ((v_ref_map->>(v_item->>'parent_ref'))::uuid,
                    (v_ref_map->>(v_item->>'child_ref'))::uuid,
                    (v_item->>'quantity')::numeric,
                    v_item->>'unit',
                    COALESCE((v_item->>'sequence')::integer, 0),
                    v_item->>'notes');
        END LOOP;
    END IF;

    -- ── Routings + nested routing_operations ──────────────────────────────
    -- Each routing is keyed by its part_ref (1:1 with the part). Operations
    -- pull work_center_id from the ref-map.
    IF v_template->'routings' IS NOT NULL THEN
        FOR v_item IN SELECT * FROM jsonb_array_elements(v_template->'routings') LOOP
            v_routing_id := gen_random_uuid();
            v_ref_map := jsonb_set(v_ref_map, ARRAY[v_item->>'_ref'], to_jsonb(v_routing_id::text));
            INSERT INTO routings (id, company_id, part_id, name, description, created_by)
            VALUES (v_routing_id, p_company_id,
                    (v_ref_map->>(v_item->>'part_ref'))::uuid,
                    v_item->>'name', v_item->>'description', p_user_id);

            IF v_item->'operations' IS NOT NULL THEN
                FOR v_inner IN SELECT * FROM jsonb_array_elements(v_item->'operations') LOOP
                    INSERT INTO routing_operations (
                        routing_id, work_center_id, sequence,
                        setup_minutes, cycle_minutes_per_unit,
                        labor_rate_override,
                        external_unit_price, external_setup_cost,
                        instructions
                    ) VALUES (
                        v_routing_id,
                        (v_ref_map->>(v_inner->>'work_center_ref'))::uuid,
                        COALESCE((v_inner->>'sequence')::integer, 10),
                        NULLIF(v_inner->>'setup_minutes', '')::numeric,
                        NULLIF(v_inner->>'cycle_minutes_per_unit', '')::numeric,
                        NULLIF(v_inner->>'labor_rate_override', '')::numeric,
                        NULLIF(v_inner->>'external_unit_price', '')::numeric,
                        NULLIF(v_inner->>'external_setup_cost', '')::numeric,
                        v_inner->>'instructions'
                    );
                END LOOP;
            END IF;
        END LOOP;
    END IF;

    -- ── Customers ─────────────────────────────────────────────────────────
    IF v_template->'customers' IS NOT NULL THEN
        FOR v_item IN SELECT * FROM jsonb_array_elements(v_template->'customers') LOOP
            v_new_id := gen_random_uuid();
            v_ref_map := jsonb_set(v_ref_map, ARRAY[v_item->>'_ref'], to_jsonb(v_new_id::text));
            INSERT INTO customers (id, company_id, name,
                                   contact_name, contact_email, contact_phone,
                                   address_line1, address_line2, city, state, postal_code, country,
                                   website)
            VALUES (v_new_id, p_company_id,
                    v_item->>'name',
                    v_item->>'contact_name', v_item->>'contact_email', v_item->>'contact_phone',
                    v_item->>'address_line1', v_item->>'address_line2',
                    v_item->>'city', v_item->>'state', v_item->>'postal_code',
                    COALESCE(v_item->>'country', 'USA'),
                    v_item->>'website');
        END LOOP;
    END IF;

    -- ── Quotes + nested line_items ────────────────────────────────────────
    -- quote_number is auto-generated by the set_quote_number trigger when
    -- left null, so we don't pass it in.
    IF v_template->'quotes' IS NOT NULL THEN
        FOR v_item IN SELECT * FROM jsonb_array_elements(v_template->'quotes') LOOP
            v_quote_id := gen_random_uuid();
            v_ref_map := jsonb_set(v_ref_map, ARRAY[v_item->>'_ref'], to_jsonb(v_quote_id::text));
            INSERT INTO quotes (id, company_id, customer_id, status,
                                lead_time_days, expiration_date, created_by)
            VALUES (v_quote_id, p_company_id,
                    CASE WHEN v_item->>'customer_ref' IS NOT NULL
                         THEN (v_ref_map->>(v_item->>'customer_ref'))::uuid
                         ELSE NULL END,
                    COALESCE(v_item->>'status', 'active'),
                    NULLIF(v_item->>'lead_time_days', '')::integer,
                    NULLIF(v_item->>'expiration_date', '')::date,
                    p_user_id);

            IF v_item->'line_items' IS NOT NULL THEN
                FOR v_inner IN SELECT * FROM jsonb_array_elements(v_item->'line_items') LOOP
                    INSERT INTO quote_line_items (
                        quote_id, company_id, part_id,
                        sequence, quantity, unit_price, total_price
                    ) VALUES (
                        v_quote_id, p_company_id,
                        (v_ref_map->>(v_inner->>'part_ref'))::uuid,
                        COALESCE((v_inner->>'sequence')::integer, 10),
                        (v_inner->>'quantity')::integer,
                        (v_inner->>'unit_price')::numeric,
                        NULLIF(v_inner->>'total_price', '')::numeric
                    );
                END LOOP;
            END IF;
        END LOOP;
    END IF;

    -- ── Jobs + job_parts ──────────────────────────────────────────────────
    -- For each job_part with a routing_ref, materialize ops + materials via
    -- create_job_part_operations_from_routing — exactly the path Convert-to-
    -- Job uses in the UI, so the demo job mirrors a realistic snapshot.
    IF v_template->'jobs' IS NOT NULL THEN
        FOR v_item IN SELECT * FROM jsonb_array_elements(v_template->'jobs') LOOP
            v_job_id := gen_random_uuid();
            v_ref_map := jsonb_set(v_ref_map, ARRAY[v_item->>'_ref'], to_jsonb(v_job_id::text));

            INSERT INTO jobs (id, company_id, customer_id, quote_id,
                              job_number, status, created_by)
            VALUES (v_job_id, p_company_id,
                    CASE WHEN v_item->>'customer_ref' IS NOT NULL
                         THEN (v_ref_map->>(v_item->>'customer_ref'))::uuid
                         ELSE NULL END,
                    CASE WHEN v_item->>'quote_ref' IS NOT NULL
                         THEN (v_ref_map->>(v_item->>'quote_ref'))::uuid
                         ELSE NULL END,
                    COALESCE(v_item->>'job_number',
                             'J-DEMO-' || substr(v_job_id::text, 1, 8)),
                    COALESCE(v_item->>'status', 'not_started'),
                    p_user_id);

            IF v_item->'parts' IS NOT NULL THEN
                FOR v_inner IN SELECT * FROM jsonb_array_elements(v_item->'parts') LOOP
                    v_part_id := (v_ref_map->>(v_inner->>'part_ref'))::uuid;
                    v_job_part_id := gen_random_uuid();

                    INSERT INTO job_parts (id, job_id, company_id, part_id,
                                           sequence, quantity, status)
                    VALUES (v_job_part_id, v_job_id, p_company_id, v_part_id,
                            COALESCE((v_inner->>'sequence')::integer, 10),
                            COALESCE((v_inner->>'quantity')::integer, 1),
                            COALESCE(v_inner->>'status', 'not_started'));

                    -- Materialize ops + materials from the routing, exactly
                    -- as Convert-to-Job does in the UI.
                    IF v_inner->>'routing_ref' IS NOT NULL THEN
                        PERFORM create_job_part_operations_from_routing(
                            v_job_part_id,
                            (v_ref_map->>(v_inner->>'routing_ref'))::uuid
                        );
                    END IF;
                END LOOP;
            END IF;
        END LOOP;
    END IF;
END;
$function$;

COMMENT ON FUNCTION public.seed_demo_data(uuid, uuid, text)
    IS 'Seeds a company from the active demo_data_templates row. Walks vendors → work_centers → parts → parts_bom → routings/routing_operations → customers → quotes/line_items → jobs/job_parts (materializing ops + materials via create_job_part_operations_from_routing). Uses a jsonb ref-map to resolve _ref → uuid across the template. Reads parts.source / parts.is_stocked from the template_data jsonb (renamed from is_manufacturable / is_stockable in the 20260504 source-enum-and-stocked-rename migration).';

COMMIT;

-- ############################################################################
-- END MIGRATION: 20260504_part_source_enum_and_stocked_rename.sql
-- ############################################################################


-- ############################################################################
-- BEGIN MIGRATION: 20260504_rebuild_demo_seed.sql
-- ############################################################################

-- ============================================================================
-- Rebuild demo seed against the unified parts/work_centers/vendors schema
-- ============================================================================
--
-- Context. The 20260502 unify-parts-inventory migration dropped the old
-- seed_demo_data, reset_demo_company, and create_demo_company functions
-- (along with operation_types, inventory_items, routing_nodes, and
-- routing_materials). Per the no-tech-debt rule, the migration also rewrote
-- demo_data_templates.template_data to a minimal known-good seed (1 vendor,
-- 2 work_centers, 3 parts, 1 routing op, 1 BOM line) and intentionally left
-- the seed/reset/create functions broken — meaning create_demo_company has
-- raised "function does not exist" since 20260502 landed.
--
-- This migration restores the three demo-mode SQL functions against the new
-- schema, AND replaces the active demo template with a richer dataset that
-- exercises every PartKind, internal + external work_centers (with
-- labor_rate_override on most internal ops to mirror the 98.6% Contour
-- pattern), BOM edges, customers, quotes with line items, and one job
-- materialized from a quote via create_job_part_operations_from_routing.
--
-- The DemoModeProvider depends on these functions for the demo-company
-- onboarding flow; once this migration runs, "Enter Demo Mode" works again.
--
-- Phase 1: Replace the active template_data with the richer seed.
-- Phase 2: Rewrite seed_demo_data() against the new schema (vendors,
--          work_centers, parts, parts_bom, routings/routing_operations,
--          customers, quotes/quote_line_items, jobs/job_parts that
--          materialize ops + materials via the new
--          create_job_part_operations_from_routing function).
-- Phase 3: Rewrite reset_demo_company() to wipe the new tables and re-seed.
-- Phase 4: Rewrite create_demo_company() to mirror the prior auth +
--          idempotency contract.

BEGIN;

-- ============================================================================
-- Phase 1: Expand demo_data_templates.template_data
-- ============================================================================
--
-- The template uses the same `_ref` ref-map pattern as the prior version
-- (each item carries _ref; sibling items reference each other via *_ref
-- fields like vendor_ref, part_ref, work_center_ref). seed_demo_data
-- resolves these into real UUIDs as it inserts.
--
-- Coverage targets (from PR 3 chunk-10 spec):
--   - 3 vendors
--   - 5 work_centers (3 internal, 2 external — one per vendor + 1 shared
--     for the EDM partner)
--   - 8 parts spanning all 4 PartKind buckets:
--       * raw stockable      (is_stockable=true,  is_manufacturable=false)
--       * raw stockable      (is_stockable=true,  is_manufacturable=false)
--       * sub-assembly       (is_stockable=true,  is_manufacturable=true)
--       * sub-assembly       (is_stockable=true,  is_manufacturable=true)
--       * manufactured       (is_stockable=false, is_manufacturable=true)
--       * manufactured       (is_stockable=false, is_manufacturable=true)
--       * manufactured       (is_stockable=false, is_manufacturable=true)
--       * unclassified       (is_stockable=false, is_manufacturable=false)
--   - 3 routings with 3-5 operations each (mixed internal/external; most
--     internal ops carry a labor_rate_override)
--   - 6 BOM edges across the manufactured + sub-assembly parents
--   - 3 customers
--   - 2 quotes with line items (one with multiple parts)
--   - 1 job materialized from the first quote

